<section class="confirmation panel"><p class="eyebrow">Account recovery</p><h1>Choose a new password</h1><?php if($done): ?><div class="flash" role="status">Your password has been updated.</div><a class="btn" href="<?= e_attr($basePath) ?>/account/login">Sign in</a><?php else: ?><?php if($error): ?><div class="store-error" role="alert"><?= e($error) ?></div><?php endif; ?><form method="post" class="checkout-form" style="text-align:left"><?= $csrf->field() ?><input type="hidden" name="token" value="<?= e_attr($token) ?>"><label>New password<input type="password" name="password" required minlength="12" autocomplete="new-password"><small class="muted">At least 12 characters with upper and lowercase letters and a number.</small></label><label>Confirm new password<input type="password" name="password_confirmation" required minlength="12" autocomplete="new-password"></label><button class="btn">Update password</button></form><?php endif; ?></section>
